{
  "tasks": [
    {
      "task_id": "T1",
      "title": "整体销售概况与订单状态分布",
      "business_question": "总体销售额、订单数量及不同订单状态的分布情况如何？",
      "priority": "P0",
      "priority_reason": "核心需求要求探索主要特征。获取整体规模（总销售额、总单量）和基础构成（订单状态计数）是理解数据全貌的最基本步骤，删除后无法回答“主要特征”中的总量与结构问题。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1_1",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "total_sales_by_status"
              },
              {
                "function": "count",
                "field": null,
                "alias": "order_count_by_status"
              }
            ],
            "dimensions": [
              "field_0004"
            ]
          }
        },
        {
          "step_id": "S1_2",
          "operation": "aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "overall_total_sales"
              },
              {
                "function": "count",
                "field": null,
                "alias": "overall_order_count"
              }
            ]
          }
        }
      ]
    },
    {
      "task_id": "T2",
      "title": "地区与城市维度的销售差异",
      "business_question": "各地区和城市的销售额及订单数量有何差异？哪些地区/城市表现突出？",
      "priority": "P0",
      "priority_reason": "核心需求要求探索“差异”。地理维度（地区、城市）通常是销售分析中最关键的分组变量，用于识别高贡献区域。删除此任务将缺失关于空间分布规律的关键洞察。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S2_1",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "sales_by_region"
              },
              {
                "function": "count",
                "field": null,
                "alias": "orders_by_region"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        },
        {
          "step_id": "S2_2",
          "operation": "sort",
          "params": {
            "field": "sales_by_region",
            "direction": "desc"
          }
        },
        {
          "step_id": "S2_3",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "sales_by_city"
              },
              {
                "function": "count",
                "field": null,
                "alias": "orders_by_city"
              }
            ],
            "dimensions": [
              "field_0003"
            ]
          }
        },
        {
          "step_id": "S2_4",
          "operation": "sort",
          "params": {
            "field": "sales_by_city",
            "direction": "desc"
          }
        }
      ]
    },
    {
      "task_id": "T3",
      "title": "产品类别的销售表现",
      "business_question": "不同产品类别的销售额和订单数量是多少？哪类产品更受欢迎或贡献更高？",
      "priority": "P0",
      "priority_reason": "核心需求要求探索“主要特征”。产品类别是业务实体的关键属性，了解品类结构对于判断业务重心至关重要。删除此任务将无法回答关于产品组合的基础问题。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S3_1",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "sales_by_category"
              },
              {
                "function": "count",
                "field": null,
                "alias": "orders_by_category"
              }
            ],
            "dimensions": [
              "field_0007"
            ]
          }
        },
        {
          "step_id": "S3_2",
          "operation": "sort",
          "params": {
            "field": "sales_by_category",
            "direction": "desc"
          }
        }
      ]
    },
    {
      "task_id": "T4",
      "title": "时间维度的销售趋势",
      "business_question": "按月份查看销售额的变化趋势，是否存在明显的季节性或周期性规律？",
      "priority": "P1",
      "priority_reason": "核心需求包含探索“规律”。虽然数据集仅10行且日期唯一，可能不足以展示显著统计规律，但时间序列是销售分析的标准维度。作为补充性分析，它有助于发现潜在的时间相关特征，若删除不影响对当前静态快照的基本描述，故定为P1。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S4_1",
          "operation": "derive",
          "params": {
            "function": "extract_month",
            "field": "field_0001",
            "alias": "order_month"
          }
        },
        {
          "step_id": "S4_2",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "monthly_sales"
              },
              {
                "function": "count",
                "field": null,
                "alias": "monthly_orders"
              }
            ],
            "dimensions": [
              "order_month"
            ]
          }
        },
        {
          "step_id": "S4_3",
          "operation": "sort",
          "params": {
            "field": "order_month",
            "direction": "asc"
          }
        }
      ]
    }
  ]
}
